/* habilidades de um componente e etapa, do nível mais fácil ao mais difícil */
function habilidadesDe(comp, etapa){
  return SAEPE_NIVEIS.filter(h => h.comp === comp && h.etapa === etapa)
    .sort((a, b) => a.nivel - b.nivel);
}
/* o ponto médio da faixa de um nível, para usar como dificuldade âncora.
   Nos extremos abertos, meio passo além da borda conhecida. */
function pontoDoNivel(h, passo){
  const p = passo || 25;
  if (h.de == null && h.ate == null) return null;
  if (h.de == null) return h.ate - p / 2;
  if (h.ate == null) return h.de + p / 2;
  return (h.de + h.ate) / 2;
}
/* descritores oficiais de um componente e etapa */
const matrizDe = (comp, etapa) => (SAEPE_MATRIZ[comp] || {})[etapa] || {};

/* índice por id, para achar a habilidade de um item em O(1) */
const SAEPE_POR_ID = {};
SAEPE_NIVEIS.forEach(h => SAEPE_POR_ID[h.id] = h);
const habilidadeDe = id => SAEPE_POR_ID[id] || null;

if (typeof module !== "undefined") module.exports =
  {SAEPE_MATRIZ, SAEPE_NIVEIS, habilidadesDe, pontoDoNivel, matrizDe,
   habilidadeDe, SAEPE_POR_ID};
